            "required": [
              "owner",
              "repo"
            ]
          }
        },
        {
          "tool_name": "github__create_pull_request_with_copilot",
          "description": "Delegate a task to GitHub Copilot coding agent to perform in the background. The agent will create a pull request with the implementation. You should use this tool if the user asks to create a pull request to perform a specific task, or if the user asks Copilot to do something.",
          "score": 4.623077869415283,
          "input_schema": {
            "type": "object",
            "properties": {
              "base_ref": {
                "type": "string",
                "description": "Git reference (e.g., branch) that the agent will start its work from. If not specified, defaults to the repository's default branch"
              },
              "owner": {
                "type": "string",
                "description": "Repository owner. You can guess the owner, but confirm it with the user before proceeding.",
                "x-mcp-header": "owner"
              },
              "problem_statement": {
                "type": "string",
                "description": "Detailed description of the task to be performed (e.g., 'Implement a feature that does X', 'Fix bug Y', etc.)"
              },
              "repo": {
                "type": "string",
                "description": "Repository name. You can guess the repository name, but confirm it with the user before proceeding.",
                "x-mcp-header": "repo"
              },
              "title": {
                "type": "string",
                "description": "Title for the pull request that will be created"
              }
            },
            "required": [
              "owner",
              "repo",
              "problem_statement",
              "title"
            ]
          }
        },
        {
          "tool_name": "github__create_repository",
          "description": "Create a new GitHub repository in your account or specified organization",
          "score": 3.630369186401367,
          "input_schema": {
            "type": "object",
            "properties": {
              "autoInit": {
                "type": "boolean",
                "description": "Initialize with README"
              },
              "description": {
                "type": "string",
                "description": "Repository description"
              },
              "name": {
                "type": "string",
                "description": "Repository name"
              },
              "organization": {
                "type": "string",
                "description": "Organization to create the repository in (omit to create in your personal account)"
              },
              "private": {
                "type": "boolean",
                "description": "Whether the repository should be private. Defaults to true (private) when omitted.",
                "default": true
              }
            },
            "required": [
              "name"
            ]
          }
        },
        {
          "tool_name": "github__create_branch",
          "description": "Create a new branch in a GitHub repository",
          "score": 3.596006393432617,
          "input_schema": {
            "type": "object",
            "properties": {
              "branch": {
                "type": "string",
                "description": "Name for new branch"
              },
              "from_branch": {
                "type": "string",
                "description": "Source branch (defaults to repo default)"
              },
              "owner": {
                "type": "string",
                "description": "Repository owner",
                "x-mcp-header": "owner"
              },
              "repo": {
                "type": "string",
                "description": "Repository name",
                "x-mcp-header": "repo"
              }
            },
            "required": [
              "owner",
              "repo",
              "branch"
            ]
          }
        },
        {
          "tool_name": "github__pull_request_review_write",
          "description": "Create and/or submit, delete review of a pull request.\n\nAvailable methods:\n- create: Create a new review of a pull request. If \"event\" parameter is provided, the review is submitted. If \"event\" is omitted, a pending review is created.\n- submit_pending: Submit an existing pending review of a pull request. This requires that a pending review exists for the current user on the specified pull request. The \"body\" and \"event\" parameters are used when submitting the review.\n- delete_pending: Delete an existing pending review of a pull request. This requires that a pending review exists for the current user on the specified pull request.\n- resolve_thread: Resolve a review thread. Requires only \"threadId\" parameter with the thread's node ID (e.g., PRRT_kwDOxxx). The owner, repo, and pullNumber parameters are not used for this method. Resolving an already-resolved thread is a no-op.\n- unresolve_thread: Unresolve a previously resolved review thread. Requires only \"threadId\" parameter. The owner, repo, and pullNumber parameters are not used for this method. Unresolving an already-unresolved thread is a no-op.\n",
          "score": 3.3574557304382324,
          "input_schema": {
            "type": "object",
            "properties": {
              "body": {
                "type": "string",
                "description": "Review comment text"
              },
              "commitID": {
                "type": "string",
                "description": "SHA of commit to review"
              },
              "event": {
                "type": "string",
                "description": "Review action to perform.",
                "enum": [
                  "APPROVE",
                  "REQUEST_CHANGES",
                  "COMMENT"
                ]
              },
              "method": {
                "type": "string",
                "description": "The write operation to perform on pull request review.",
                "enum": [
                  "create",
                  "submit_pending",
                  "delete_pending",
                  "resolve_thread",
                  "unresolve_thread"
                ]
              },
              "owner": {
                "type": "string",
                "description": "Repository owner",
                "x-mcp-header": "owner"
              },
              "pullNumber": {
                "type": "number",
                "description": "Pull request number"
              },
              "repo": {
                "type": "string",
                "description": "Repository name",
                "x-mcp-header": "repo"
              },
              "threadId": {
                "type": "string",
                "description": "The node ID of the review thread (e.g., PRRT_kwDOxxx). Required for resolve_thread and unresolve_thread methods. Get thread IDs from pull_request_read with method get_review_comments."
              }
            },
            "required": [
              "method",
              "owner",
              "repo",
              "pullNumber"
            ]
          }
        },
        {
          "tool_name": "github__create_repository_ruleset",
          "description": "Create a new ruleset at the repository, organization, or enterprise level",
          "score": 3.2819583415985107,
          "input_schema": {
            "type": "object",
            "properties": {
              "bypass_actors": {
                "type": "array",
                "items": {
                  "type": "object",
                  "properties": {
                    "actor_id": {
                      "type": "number",
                      "description": "The ID of the actor that can bypass a ruleset"
                    },
                    "actor_type": {
                      "type": "string",
                      "description": "The type of actor that can bypass a ruleset. 'EnterpriseOwner' and 'EnterpriseRole' are only valid for 'enterprise' level rulesets.",
                      "enum": [
                        "Integration",
                        "OrganizationAdmin",
                        "RepositoryRole",
                        "Team",
                        "DeployKey",
                        "User",
                        "EnterpriseOwner",
                        "EnterpriseRole"
                      ]
                    },
                    "bypass_mode": {
                      "type": "string",
                      "description": "When the specified actor can bypass the ruleset. 'pull_request' only applies to branch rulesets and is not valid for the 'DeployKey' actor type. 'exempt' means rules are not run for that actor and no bypass audit entry is created.",
                      "enum": [
                        "always",
                        "pull_request",
                        "exempt"
                      ]
                    }
                  },
                  "required": [
                    "actor_type",
                    "bypass_mode"
                  ],
                  "additionalProperties": false
                },
                "description": "The actors that can bypass the rules in this ruleset"
              },
              "conditions": {
                "type": "object",
                "description": "Conditions for when this ruleset applies, e.g. {\"ref_name\": {\"include\": [\"refs/heads/main\"], \"exclude\": []}}"
              },
              "enforcement": {
                "type": "string",
                "description": "The enforcement level of the ruleset. 'evaluate' allows admins to test rules before enforcing them",
                "enum": [
                  "disabled",
                  "active",
                  "evaluate"
                ]
              },
              "enterprise": {
                "type": "string",
                "description": "Enterprise slug. Required when level is 'enterprise'."
              },
              "level": {
                "type": "string",
                "description": "The level at which the ruleset is configured:\n- 'repository': A ruleset on a single repository (requires 'owner' and 'repo').\n- 'organization': A ruleset covering repositories in an organization (requires 'org').\n- 'enterprise': A ruleset covering repositories across an enterprise (requires 'enterprise').",
                "enum": [
                  "repository",
                  "organization",
                  "enterprise"
                ]
              },
              "name": {
                "type": "string",
                "description": "The name of the ruleset"
              },
              "org": {
                "type": "string",
                "description": "Organization name. Required when level is 'organization'."
              },
              "owner": {
                "type": "string",
                "description": "Repository owner. Required when level is 'repository'.",
                "x-mcp-header": "owner"
              },
              "repo": {
                "type": "string",
                "description": "Repository name. Required when level is 'repository'.",
                "x-mcp-header": "repo"
              },
              "rules": {
                "type": "array",
                "items": {
                  "type": "object",
                  "properties": {
                    "parameters": {
                      "type": "object",
                      "description": "Parameters for rule types that require additional configuration"
                    },
                    "type": {
                      "type": "string",
                      "description": "The type of rule, e.g. 'creation', 'deletion', 'non_fast_forward', 'required_signatures', 'pull_request', 'required_status_checks'"
                    }
                  },
                  "required": [
                    "type"
                  ],
                  "additionalProperties": false
                },
                "description": "An array of rules within the ruleset. Each rule is an object with a 'type' (e.g. 'creation', 'deletion', 'non_fast_forward', 'required_signatures', 'pull_request', 'required_status_checks') and, for rules that need configuration, a 'parameters' object"
              },
              "target": {
                "type": "string",
                "description": "The target of the ruleset. Defaults to 'branch'. 'repository' is only valid for 'organization' and 'enterprise' level rulesets.",
                "enum": [
                  "branch",
                  "tag",
                  "push",
                  "repository"
                ]
              }
            },
            "required": [
              "level",
              "name",
              "enforcement",
              "rules"
            ],
            "additionalProperties": false
          }
        },
        {
          "tool_name": "github__create_pull_request",
          "description": "Create a new pull request in a GitHub repository.",
          "score": 3.2115917205810547,
          "input_schema": {
            "type": "object",
            "properties": {
              "base": {
                "type": "string",
                "description": "Branch to merge into"
              },
              "body": {
                "type": "string",
                "description": "PR description"
              },
              "draft": {
                "type": "boolean",
                "description": "Create as draft PR"
              },
              "head": {
                "type": "string",
                "description": "Branch containing changes"
              },
              "maintainer_can_modify": {
                "type": "boolean",
                "description": "Allow maintainer edits"
              },
              "owner": {
                "type": "string",
                "description": "Repository owner",
                "x-mcp-header": "owner"
              },
              "repo": {
                "type": "string",
                "description": "Repository name",
                "x-mcp-header": "repo"
              },
              "reviewers": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "description": "GitHub usernames or ORG/team-slug team reviewers to request reviews from"
              },
              "title": {
                "type": "string",
                "description": "PR title"
              }
            },
            "required": [
              "owner",
              "repo",
              "title",
              "head",
              "base"
            ]
          }
        },
        {
          "tool_name": "github__create_gist",
          "description": "Create a new gist",
          "score": 2.9298527240753174,
          "input_schema": {
            "type": "object",
            "properties": {
              "content": {
                "type": "string",
                "description": "Content for simple single-file gist creation"
              },
              "description": {
                "type": "string",
                "description": "Description of the gist"
              },
              "filename": {
                "type": "string",
                "description": "Filename for simple single-file gist creation"
              },
              "public": {
                "type": "boolean",
                "description": "Whether the gist is public",
                "default": false
              }
            },
            "required": [
              "filename",
              "content"
            ]
          }
        },
        {
          "tool_name": "github__create_or_update_file",
          "description": "Create or update a single file in a GitHub repository. \nIf updating, you should provide the SHA of the file you want to update. Use this tool to create or update a file in a GitHub repository remotely; do not use it for local file operations.\n\nTo obtain the current blob SHA before updating, call the get_file_contents tool with the same owner, repo, and path, and set its ref parameter to this tool's branch value. The first text result reports the blob SHA for the requested path.\n\nSHA MUST be provided for existing file updates.\n",
          "score": 2.8995208740234375,
          "input_schema": {
            "type": "object",
            "properties": {
              "allow_symlink_write": {
                "type": "boolean",
                "description": "Set true to update a symbolic link itself; content must be its new target path.",
                "default": false
              },
              "branch": {
                "type": "string",
                "description": "Branch to create/update the file in"
              },
              "content": {
                "type": "string",
                "description": "Content of the file, exactly as it should appear once written. Do not base64-encode it; this server does that before calling the REST API."
              },
              "message": {
                "type": "string",
                "description": "Commit message"
              },
              "owner": {
                "type": "string",
                "description": "Repository owner (username or organization)",
                "x-mcp-header": "owner"
              },
              "path": {
                "type": "string",
                "description": "Path where to create/update the file"
              },
              "repo": {
                "type": "string",
                "description": "Repository name",
                "x-mcp-header": "repo"
              },
              "sha": {
                "type": "string",
                "description": "The blob SHA of the file being replaced. Required if the file already exists. Retrieve it with get_file_contents using the same owner, repo, and path, with ref set to this tool's branch value."
              }
            },
            "required": [
              "owner",
              "repo",
              "path",
              "content",
              "message",
              "branch"
            ]
          }
        },
        {
          "tool_name": "github__get_teams",
          "description": "Get details of the teams the user is a member of. Limited to organizations accessible with current credentials",
          "score": 2.687730312347412,
          "input_schema": {
            "type": "object",
            "properties": {
              "user": {
                "type": "string",
                "description": "Username to get teams for. If not provided, uses the authenticated user."
              }
            }
          }
        },
        {
          "tool_name": "github__get_me",
          "description": "Get details of the authenticated GitHub user. Use this when a request is about the user's own profile for GitHub. Or when information is missing to build other tool calls.",
          "score": 2.43497633934021,
          "input_schema": {
            "type": "object",
            "properties": {}
          }
        }
      ]
    },
    {
      "server": "tasks",
      "tools": [
        {
          "tool_name": "tasks__create",
          "description": "Create a new automation: Grok runs the prompt on a schedule and/or when an event fires (Gmail/Outlook email, GitHub, Finance, Linear, …), and optionally notifies the user. Use this when the user asks to create an automation, reminder, scheduled task, recurring check, or an event-triggered automation — every morning, daily, weekly, at a specific future time, or when an email / GitHub / finance / Linear event matches. Put the complete automation in this one call. Do not create a name/prompt shell and then call automation_update in the same turn — if anything is missing or illegal, create fails and you retry create (or call automation_validate first). Call `automation_validate` to preview the parsed schedule and resolved resource ids before creating. Before creating an automation that uses a third-party service (Gmail, Outlook, Slack, Notion, Linear, GitHub, calendar, finance, …) — as an event trigger or inside the prompt — call `search_connected_tools` with that service name (e.g. 'gmail', 'slack'). A valid connection exists only when results include tools whose `remote_name` is that service (e.g. 'Gmail'), not Automations tools that merely mention it. If none appear, do not create the automation; call `request_connector_auth` (connector = service name, reason = what the automation will do) so the user can connect, then retry after they connect. Webhook triggers need no connector. Pure schedule automations that do not use a connected service can be created immediately. For event triggers: call `automation_list_trigger_catalog` first (feature flags control which providers appear), then set `trigger` with provider, trigger_type, and dimensions (or email aliases from/to/subject_contains). Prefer numeric GitHub repository ids and Linear UUIDs from `automation_list_trigger_resources`. owner/name (e.g. xai-org/xai) and Linear team/project/author display names are resolved when they uniquely match; ambiguous or unknown values fail — retry create with the id, do not update. Omit schedule fields for trigger-o… [truncated]",
          "score": 3.922581911087036,
          "input_schema": {
            "type": "object",
            "properties": {
              "name": {
                "type": "string",
                "description": "Short name for the automation (e.g. 'bitcoin-price-check' or 'emails-from-alice')"
              },
              "prompt": {
                "type": "string",
                "description": "The prompt Grok will execute on each run"
              },
              "cadence": {
                "type": "string",
                "description": "RFC 5545 RRULE describing how often the automation runs. Supported forms:\n- \"RRULE:FREQ=DAILY\" (every day)\n- \"RRULE:FREQ=WEEKLY;BYDAY=MO\" (one weekday) or \"RRULE:FREQ=WEEKLY;BYDAY=MO,WE,FR\" (several weekdays), \"RRULE:FREQ=WEEKLY;BYDAY=MO,TU,WE,TH,FR\" for every weekday\n- \"RRULE:FREQ=MONTHLY;BYMONTHDAY=15\" (a day of the month)\n- \"RRULE:FREQ=YEARLY\" (once a year)\n- \"RRULE:FREQ=HOURLY\" (every hour). Restrict an hourly cadence to a daily time range via window_start_time / window_end_time and to certain days via BYDAY (e.g. \"RRULE:FREQ=HOURLY;BYDAY=MO,TU,WE,TH,FR\").\nOmit / empty with no trigger → run only once. Omit with a `trigger` → trigger-only (no schedule). Do not include DTSTART/DTEND — use time_of_day + timezone (and window_start_time / window_end_time for hourly) instead."
              },
              "scheduled_date": {
                "type": "string",
                "description": "ISO 8601 date for one-time automations (e.g. '2026-05-25'). Required when cadence is omitted for a schedule (run-once). Defaults to today if not provided. Omit together with cadence when creating a trigger-only automation."
              },
              "time_of_day": {
                "type": "string",
                "description": "Time in 24h format (e.g. '09:00') for a scheduled run. Defaults to '09:00' when a schedule is created. With a `trigger`, only set this together with cadence/scheduled_date — alone it does not create a schedule. Ignored for hourly cadences (use window_start_time)."
              },
              "window_start_time": {
                "type": "string",
                "description": "For hourly (FREQ=HOURLY) automations only: start of the daily run window in 24h 'HH:MM' (e.g. '09:00'). Must be strictly before window_end_time; omit both to run every hour all day."
              },
              "window_end_time": {
                "type": "string",
                "description": "For hourly (FREQ=HOURLY) automations only: inclusive end of the daily run window in 24h 'HH:MM' (e.g. '18:00' still fires at 18:00). Omit both to run every hour all day."
              },
              "timezone": {
                "type": "string",
                "description": "IANA timezone (e.g. 'America/New_York'). Defaults to user's timezone."
              },
              "notification": {
                "type": "string",
                "enum": [
                  "default",
                  "email_only",
                  "app_only",
                  "off"
                ],
                "description": "Notification method. Defaults to 'default' (email + app)."
              },
              "trigger": {
                "type": "object",
                "description": "Optional event trigger. Confirm the provider is connected via search_connected_tools first (see tool description); if it is not, call request_connector_auth instead of creating. Then call automation_list_trigger_catalog — only listed providers/types/dimensions are available for this account (some are feature-flagged: GitHub, Finance, Linear, …). Prefer `dimensions` map with catalog keys. For email (gmail/outlook) you may use from/to/subject_contains aliases instead; at least one email filter is required. Defaults: trigger_type new_email for gmail/outlook. Webhook needs no connector.",
                "properties": {
                  "provider": {
                    "type": "string",
                    "description": "Event source wire tag from the catalog (e.g. gmail, outlook, github, finance, linear)."
                  },
                  "trigger_type": {
                    "type": "string",
                    "description": "Event kind from the catalog (e.g. new_email, pr_opened, new_transaction, issue_created). Required except gmail/outlook (default new_email) and webhook."
                  },
                  "dimensions": {
                    "type": "object",
                    "description": "Catalog dimension keys → string or array of strings (e.g. {\"from\":[\"@x.ai\"], \"repo\":[\"314159\"], \"team\":[\"<linear-team-uuid>\"], \"amount_min\":\"50\"}). Keys must match the catalog entry for this trigger_type. Prefer stringified numeric GitHub repository ids and Linear UUIDs from automation_list_trigger_resources. owner/name (xai-org/xai) and Linear team/project/author display names are resolved when they uniquely match; otherwise create fails — call automation_list_trigger_resources and retry create.",
                    "additionalProperties": {
                      "oneOf": [
                        {
                          "type": "string"
                        },
                        {
                          "type": "array",
                          "items": {
                            "type": "string"
                          }
                        }
                      ]
                    }
                  },
                  "from": {
                    "description": "Email alias for dimensions.from: full email or @domain. String or array.",
                    "oneOf": [
                      {
                        "type": "string"
                      },
                      {
                        "type": "array",
                        "items": {
                          "type": "string"
                        }
                      }
                    ]
                  },
                  "to": {
                    "description": "Email alias for dimensions.to: full email or @domain. String or array.",
                    "oneOf": [
                      {
                        "type": "string"
                      },
                      {
                        "type": "array",
                        "items": {
                          "type": "string"
                        }
                      }
                    ]
                  },
                  "subject_contains": {
                    "description": "Email alias for dimensions.subject_contains. String or array.",
                    "oneOf": [
                      {
                        "type": "string"
                      },
                      {
                        "type": "array",
                        "items": {
                          "type": "string"
                        }
                      }
                    ]
                  }
                },
                "required": [
                  "provider"
                ]
              }
            },
            "required": [
              "name",
              "prompt"
            ]
          }
        },
        {
          "tool_name": "tasks__list_trigger_catalog",
          "description": "List event-trigger providers, types, and filter dimensions available to this account. If `groups` is empty, event triggers are not enabled — do not create or update a Gmail, Outlook, GitHub, Finance, Linear, or Webhook trigger. Some providers are also feature-flagged and may be absent (e.g. GitHub, Finance, Linear). A provider appearing here does not mean the user is connected. Before authoring a trigger for Gmail, Outlook, GitHub, Linear, finance, Slack, Notion, or similar, call `search_connected_tools` for that service; if no tools with that `remote_name` appear, call `request_connector_auth` instead of creating the trigger. Webhook needs no connector. Call this before automation_create / automation_update with a `trigger`. Use the returned provider / trigger_type / dimensions keys when building the trigger args. For GitHub repository filters, also call automation_list_trigger_resources to resolve owner/name to the numeric repository id required by dimensions.repo. When Linear is listed, call the same tool (provider=linear, resource_type=team|project) for team/project UUIDs, or resource_type=author (no repo_ids) for actor / assignee / issue-creator user UUIDs. Use when the user wants an email, Outlook, GitHub, finance/transaction, Linear, or other event-triggered automation and you need the available options.",
          "score": 3.5067410469055176,
          "input_schema": {
            "type": "object",
            "properties": {}
          }
        },
