        payload=json.loads(payload)
        print('decoded payload keys', list(payload.keys())[:50])
    except Exception as e:
        print('payload string len', len(payload), e)
elif isinstance(payload, dict):
    print('payload keys', list(payload.keys())[:80])
    def walk(obj, prefix='', depth=0):
        if depth>5: return
        if isinstance(obj, dict):
            for k,v in obj.items():
                path=f'{prefix}.{k}' if prefix else k
                lk=str(k).lower()
                interesting = any(x in lk for x in ['git','mcp','token','github','plugin','server','oauth','credential'])
