                    else:
                        print('PATH', path, type(v).__name__, 'len', len(str(v)))
                walk(v, path, depth+1)
        elif isinstance(obj, list) and len(obj)>0 and isinstance(obj[0], dict) and depth<3:
            walk(obj[0], prefix+'[0]', depth+1)
    walk(payload)

# look for mcp config files
