import json, urllib.request, urllib.error
headers={'User-Agent':'ebd-ai-setup','Accept':'application/vnd.github+json'}
for url in [
    'https://api.github.com/orgs/HAISymbiosis',
    'https://api.github.com/orgs/HAISymbiosis/repos?per_page=5',
    'https://api.github.com/users/jandreu/orgs',
    'https://api.github.com/orgs/Mybotstaff',
]:
    print('\nGET', url)
    req=urllib.request.Request(url, headers=headers)
    try:
        with urllib.request.urlopen(req) as r:
            body=r.read().decode()
            print('status', r.status)
            try:
                d=json.loads(body)
            except Exception:
                print(body[:400]); continue
            if isinstance(d, dict):
                keys=['login','id','description','html_url','type','public_repos','total_private_repos']
                print({k:d.get(k) for k in keys if k in d})
            elif isinstance(d, list):
                print('list len', len(d))
                for item in d[:10]:
                    if isinstance(item, dict):
                        print(' ', item.get('login') or item.get('full_name') or item.get('name'))
    except urllib.error.HTTPError as e:
        print('status', e.code, e.read(400).decode())
PY
