python3 - <<'PY'
import os
pid=None
for p in os.listdir('/proc'):
    if not p.isdigit(): continue
    try:
        cmd=open(f'/proc/{p}/cmdline','rb').read().replace(b'\x00',b' ').decode('utf-8','ignore')
    except Exception:
        continue
    if 'grok-linux' in cmd or '/usr/bin/qemu-aarch64' in cmd and 'grok' in cmd:
        print('pid', p, cmd[:120])
        try:
            env=open(f'/proc/{p}/environ','rb').read().split(b'\x00')
        except Exception as e:
            print(' env err', e); continue
        names=[]
        for e in env:
            if not e: continue
            k=e.split(b'=',1)[0].decode('utf-8','ignore')
            names.append(k)
            lk=k.lower()
